/**
 * Unduhan dokumen di prototipe (PRD Scope 1 FR-PD-007). File asli tidak disimpan, jadi isi file dibuat di browser:
 * PDF satu halaman berisi nama dokumen, atau JPEG placeholder 1x1 untuk foto. Nama file = nama file dokumen.
 */
const JPEG_B64 = '';

/** PDF minimal (1 halaman, teks nama file) dengan tabel xref yang valid. */
export function placeholderPdf(title) {
  const text = String(title).replace(/[^\x20-\x7e]|[()\\]/g, '');
  const stream = `BT /F1 14 Tf 72 760 Td (${text}) Tj ET`;
  const objs = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>',
    `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
  ];
  let out = '%PDF-1.4\n';
  const offsets = objs.map((o, i) => { const at = out.length; out += `${i + 1} 0 obj\n${o}\nendobj\n`; return at; });
  const xref = out.length;
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n${offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('')}`;
  out += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return new Blob([out], { type: 'application/pdf' });
}

/** File placeholder sesuai ekstensi nama file. */
export function placeholderFile(name) {
  if (/\.pdf$/i.test(name)) return placeholderPdf(name);
  const bin = atob(JPEG_B64);
  return new Blob([Uint8Array.from(bin, (c) => c.charCodeAt(0))], { type: 'image/jpeg' });
}

/** Simpan Blob ke perangkat lewat <a download>. */
export function saveBlob(blob, name) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}
